    sv.remove(mf1);
    assertTrue(sv.isEmpty());
    assertEquals(0, sv.size());
    assertNull(sv.get(mf1));
    sv.put(mf1, true);
    assertFalse(sv.isEmpty());
    assertEquals(1, sv.size());
    assertEquals(true, sv.get(mf1));
    sv.remove(mf1);
    assertTrue(sv.isEmpty());
    assertEquals(0, sv.size());
    assertNull(sv.get(mf1));
    sv.remove(mf1);
    assertTrue(sv.isEmpty());
    assertEquals(0, sv.size());
    assertNull(sv.get(mf1));
}

