/**
 * Tests reading a pre-canned add message.
 * @throws Exception
 */
@Test
public void test_add_in() throws Exception {
    Type add = vf.getType("add");
    Field x = new Field("x");
    add.putValidator(x, Validator_int.get(0));
    Field y = new Field("y");
    add.putValidator(y, Validator_int.get(0));
    Field _mf__messageId = DefaultValueFactory._mf__messageId;
    add.putValidator(_mf__messageId, Validator_long.get(0));
    long msgid = 0x0123456789abcdefL;
    byte[] buf = { // version
    3, // INT (type)
    -122, // add
    39, // add
    -23, // add
    -73, // add
    -100, // length
    3, // INT (key)
    -122, 99, 6, -76, 104, // LONG (value)
    -121, 1, 35, 69, 103, -119, -85, -51, -17, // INT (key)
    -122, // y
    21, // y
    10, // y
    44, // y
    -76, // tiny int = 2 (value)
    2, // INT (key)
    -122, // x
    21, // x
    10, // x
    44, // x
    -77, // tiny int = 1 (value)
    1, // NONE
    -127 };
    Message msg = bytes2msg(buf);
    msg.checkType(add);
    Assert.assertEquals(3, msg.size());
    Assert.assertEquals(1, msg.get(x));
    Assert.assertEquals(2, msg.get(y));
    Assert.assertEquals(msgid, msg.get(_mf__messageId));
    buf = new byte[] { // version
    3, // INT (type)
    -122, // add
    39, // add
    -23, // add
    -73, // add
    -100, // length
    3, // INT (key)
    -122, 99, 6, -76, 104, // LONG (value)
    -121, 1, 35, 69, 103, -119, -85, -51, -17, // INT (key)
    -122, // y
    21, // y
    10, // y
    44, // y
    -76, // INT (value)
    -122, 119, 53, -108, 0, // INT (key)
    -122, // x
    21, // x
    10, // x
    44, // x
    -77, // INT (value)
    -122, 59, -102, -54, 0, // NONE
    -127 };
    msg = bytes2msg(buf);
    msg.checkType(add);
    Assert.assertEquals(3, msg.size());
    Assert.assertEquals(1000000000, msg.get(x));
    Assert.assertEquals(2000000000, msg.get(y));
    Assert.assertEquals(msgid, msg.get(_mf__messageId));
}

