            } catch (InterruptedException e) {
                // e.printStackTrace();
            }
        }
    }, "t2");
    t1.start();
    t2.start();
    // wait until both threads are waiting on queue...
    Thread.sleep(100);
    synchronized (queue) {
        queue.put(1);
        queue.put(2);
    }
    harvest(t1);
    harvest(t2);
}

